import re

def parse_grid(text, label_pattern):
    m=re.search(label_pattern+r'\s*\n((?:[0-9 ]+\n)+)', text)
    if not m: raise ValueError(label_pattern)
    return [[int(x) for x in line.split()] for line in m.group(1).strip().splitlines()]

