from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=8 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            colors={grid[y][x] for y,x in cells if grid[y][x] not in (0,8)}
            if len(colors)!=1:
                continue
            color=next(iter(colors))
            ys=[y for y,x in cells if grid[y][x]==color]
            xs=[x for y,x in cells if grid[y][x]==color]
            r0,r1=min(ys),max(ys); c0,c1=min(xs),max(xs)
            ph,pw=r1-r0+1,c1-c0+1
            motif=[row[c0:c1+1] for row in grid[r0:r1+1]]
            for y,x in cells:
                out[y][x]=motif[(y-r0)%ph][(x-c0)%pw]
    return out

